push!(LOAD_PATH, @__DIR__)
using FloatAbstractions
using SoftFloats: SoftFloat


function check_selbtz_two_sum_lemmas(
    value_map::Dict{SELBTZAbstraction,Vector{T}},
) where {T}

    ± = false:true
    p = precision(T)
    pos_zero = SELBTZAbstraction(zero(T))
    neg_zero = SELBTZAbstraction(-zero(T))
    abstract_inputs = sort!(collect(keys(value_map)))
    lemma_counts = Dict{String,Int}()

    for x in abstract_inputs, y in abstract_inputs

        sx, lbx, ex, fx, gx = unpack(x, T)
        sy, lby, ey, fy, gy = unpack(y, T)
        same_sign = (sx == sy)
        diff_sign = (sx != sy)
        x_zero = (x == pos_zero) | (x == neg_zero)
        y_zero = (y == pos_zero) | (y == neg_zero)
        checker = LemmaChecker(
            two_sum_abstractions(value_map, x, y), x, y, T, lemma_counts)

        #! format: off
        if x_zero | y_zero ###################################### LEMMA FAMILY Z

            checker("SELBTZ-TwoSum-Z1-P", x_zero & y_zero & !(sx & sy)) do lemma
                add_case!(lemma, pos_zero, pos_zero)
            end
            checker("SELBTZ-TwoSum-Z1-N", x_zero & y_zero & sx & sy) do lemma
                add_case!(lemma, neg_zero, pos_zero)
            end

            checker("SELBTZ-TwoSum-Z2-X", y_zero & !x_zero) do lemma
                add_case!(lemma, x, pos_zero)
            end
            checker("SELBTZ-TwoSum-Z2-Y", x_zero & !y_zero) do lemma
                add_case!(lemma, y, pos_zero)
            end

        else ############################################ NONZERO LEMMA FAMILIES

            ###################################################### CODIMENSION 0

            checker("SELBTZ-TwoSum-I0-X",
                (ex > ey + (p+1)) |
                (!lby & (ex == ey + p) & (ey == gy) & (ex < gx + (p-1)) & (same_sign | (ex > gx))) |
                ((ex == ey + (p+1)) & (same_sign | (ex > gx) | (!lby & (ey == gy))))
            ) do lemma
                add_case!(lemma, x, y)
            end
            checker("SELBTZ-TwoSum-I0-Y",
                (ey > ex + (p+1)) |
                (!lbx & (ey == ex + p) & (ex == gx) & (ey < gy + (p-1)) & (same_sign | (ey > gy))) |
                ((ey == ex + (p+1)) & (same_sign | (ey > gy) | (!lbx & (ex == gx))))
            ) do lemma
                add_case!(lemma, y, x)
            end

            checker("SELBTZ-TwoSum-L1a-X",
                (same_sign != lbx) &
                (ex > ey + 1) & (gx < gy) &
                ((fx < fy) | (fx < gy) | (!lby & (fx < ey - 1)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-L1a-Y",
                (same_sign != lby) &
                (ey > ex + 1) & (gy < gx) &
                ((fy < fx) | (fy < gx) | (!lbx & (fy < ex - 1)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-L1b-X",
                (same_sign != lbx) &
                (ex > ey + 2) & (fx < ey + 1) & (fx > fy) & (gx < gy) &
                (lby | (fx == ey))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey+1, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-L1b-Y",
                (same_sign != lby) &
                (ey > ex + 2) & (fy < ex + 1) & (fy > fx) & (gy < gx) &
                (lbx | (fy == ex))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex+1, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-L1c-X",
                same_sign & lbx &
                (ex > ey) & (fx < ey - 1) & (gx < gy) &
                (ex < gx + (p-1)) &
                (lby | (fx < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-L1c-Y",
                same_sign & lby &
                (ey > ex) & (fy < ex - 1) & (gy < gx) &
                (ey < gy + (p-1)) &
                (lbx | (fy < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-L1d-X",
                same_sign & lbx &
                (ex > ey - 1) & (fx > fy - 1) & (gx < gy) &
                (ex < gx + (p-1)) &
                (
                    (!lby & (fx < ey - 1) & ((gy == fy) | (fx > fy))) |
                    (lby & (fx == ey - 1) & (fx == gy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ey-1, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-L1d-Y",
                same_sign & lby &
                (ey > ex - 1) & (fy > fx - 1) & (gy < gx) &
                (ey < gy + (p-1)) &
                (
                    (!lbx & (fy < ex - 1) & ((gx == fx) | (fy > fx))) |
                    (lbx & (fy == ex - 1) & (fy == gx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ex-1, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-L1e-X",
                diff_sign & !lbx &
                (ex > ey + 2) & (fx < ey - 1) & (gx < gy) &
                (lby | (fx < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-L1e-Y",
                diff_sign & !lby &
                (ey > ex + 2) & (fy < ex - 1) & (gy < gx) &
                (lbx | (fy < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-L1f-X",
                diff_sign & !lbx &
                (ex > ey + 1) & (gx < gy) &
                (
                    (!lby & (fx < ey - 1) & ((fx > fy) | ((fx == fy) & (fx == gy)))) |
                    (lby & (fx == ey - 1) & (gy == fx))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey-1, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-L1f-Y",
                diff_sign & !lby &
                (ey > ex + 1) & (gy < gx) &
                (
                    (!lbx & (fy < ex - 1) & ((fy > fx) | ((fy == fx) & (fy == gx)))) |
                    (lbx & (fy == ex - 1) & (gx == fy))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex-1, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-T1-X",
                (gx > ey) &
                (ex < gy + p) &
                ((gx < fx) | (same_sign & (fx > ey)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, gy), pos_zero)
            end
            checker("SELBTZ-TwoSum-T1-Y",
                (gy > ex) &
                (ey < gx + p) &
                ((gy < fy) | (same_sign & (fy > ex)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, gx), pos_zero)
            end

            checker("SELBTZ-TwoSum-T2-X",
                !lby &
                (fx > ey) & (gx > ey) &
                (ex < fy + (p+1)) & (ex > gy + p) &
                (same_sign | (gx < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(~sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(~sy, 0, gy, gy-p, gy))
                for ee = gy+1:ex-(p+1)
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(sy, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(sy, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(sy, 1, ee, gy+1:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(~sy, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(~sy, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(~sy, 1, ee, gy+1:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(~sy, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(~sy, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(~sy, 1, ee, gy+1:ee-2, gy))
                end
            end
            checker("SELBTZ-TwoSum-T2-Y",
                !lbx &
                (fy > ex) & (gy > ex) &
                (ey < fx + (p+1)) & (ey > gx + p) &
                (same_sign | (gy < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(~sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(~sx, 0, gx, gx-p, gx))
                for ee = gx+1:ey-(p+1)
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(sx, 1, ee, gx-1, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(sx, 0, ee, gx:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(sx, 1, ee, gx+1:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(~sx, 1, ee, gx-1, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(~sx, 0, ee, gx:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(~sx, 1, ee, gx+1:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(~sx, 1, ee, gx-1, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(~sx, 0, ee, gx:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(~sx, 1, ee, gx+1:ee-2, gx))
                end
            end

            checker("SELBTZ-TwoSum-T3-X",
                lby &
                (fx > ey) & (gx > ey) &
                (ex < fy + (p+1)) & (ex > gy + p) &
                (same_sign | (gx < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(~sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(sy, 0, gy, gy-p, gy))
                for ee = gy+1:ex-(p+1)
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(~sy, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(~sy, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy), SELBTZRange(~sy, 1, ee, gy+1:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(sy, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(sy, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ex-(p-1):fy-1), SELBTZRange(sy, 1, ee, gy+1:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(sy, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(sy, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, fy+1), SELBTZRange(sy, 1, ee, gy+1:ee-2, gy))
                end
            end
            checker("SELBTZ-TwoSum-T3-Y",
                lbx &
                (fy > ex) & (gy > ex) &
                (ey < fx + (p+1)) & (ey > gx + p) &
                (same_sign | (gy < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(~sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(sx, 0, gx, gx-p, gx))
                for ee = gx+1:ey-(p+1)
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(~sx, 1, ee, gx-1, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(~sx, 0, ee, gx:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx), SELBTZRange(~sx, 1, ee, gx+1:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(sx, 1, ee, gx-1, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(sx, 0, ee, gx:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ey-(p-1):fx-1), SELBTZRange(sx, 1, ee, gx+1:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(sx, 1, ee, gx-1, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(sx, 0, ee, gx:ee-2, gx))
                    add_case!(lemma, SELBTZRange(sy, lby, ey, fy, fx+1), SELBTZRange(sx, 1, ee, gx+1:ee-2, gx))
                end
            end

            checker("SELBTZ-TwoSum-T4-X",
                !lby &
                (fx > ey) & (gx > ey) & (gy < fy) &
                (ex < ey + p) & (ex > fy + p) &
                (same_sign | (gx < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ey), SELBTZRange(sy, 1, fy, gy-1, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ey), SELBTZRange(sy, 0, fy, gy:fy-2, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ey), SELBTZRange(sy, 1, fy, gy+1:fy-2, gy))
            end
            checker("SELBTZ-TwoSum-T4-Y",
                !lbx &
                (fy > ex) & (gy > ex) & (gx < fx) &
                (ey < ex + p) & (ey > fx + p) &
                (same_sign | (gy < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ex), SELBTZRange(sx, 1, fx, gx-1, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ex), SELBTZRange(sx, 0, fx, gx:fx-2, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ex), SELBTZRange(sx, 1, fx, gx+1:fx-2, gx))
            end

            checker("SELBTZ-TwoSum-T5-X",
                lby &
                (fx > ey + 1) & (gx > ey + 1) & (gy < fy) &
                (ex < ey + (p+1)) & (ex > fy + p) &
                (same_sign | (gx < fx))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ey+1), SELBTZRange(~sy, 1, fy, gy-1, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ey+1), SELBTZRange(~sy, 0, fy, gy:fy-2, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx, ey+1), SELBTZRange(~sy, 1, fy, gy+1:fy-2, gy))
            end
            checker("SELBTZ-TwoSum-T5-Y",
                lbx &
                (fy > ex + 1) & (gy > ex + 1) & (gx < fx) &
                (ey < ex + (p+1)) & (ey > fx + p) &
                (same_sign | (gy < fy))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ex+1), SELBTZRange(~sx, 1, fx, gx-1, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ex+1), SELBTZRange(~sx, 0, fx, gx:fx-2, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy, ex+1), SELBTZRange(~sx, 1, fx, gx+1:fx-2, gx))
            end

            checker("SELBTZ-TwoSum-M1Cx-X",
                (same_sign != lbx) &
                (fx < ex - 2) & (fx > ey) & (gx < gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx:fx+1, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-M1Cx-Y",
                (same_sign != lby) &
                (fy < ey - 2) & (fy > ex) & (gy < gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy:fy+1, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-M1Cy-X",
                (same_sign != lbx) &
                (fx < ex - 2) & (fx > ey) & (gx < ey + 1) & (gx > gy) &
                (ex < gy + p) &
                ((fx > ey + 1) | (gx < fy + 1) | (!lby & (gx < ey)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx:fx+1, gy), pos_zero)
            end
            checker("SELBTZ-TwoSum-M1Cy-Y",
                (same_sign != lby) &
                (fy < ey - 2) & (fy > ex) & (gy < ex + 1) & (gy > gx) &
                (ey < gx + p) &
                ((fy > ex + 1) | (gy < fx + 1) | (!lbx & (gy < ex)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy:fy+1, gx), pos_zero)
            end

            checker("SELBTZ-TwoSum-M1Gx-X",
                (same_sign == lbx) &
                (fx > ey + 1) & (gx < gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx-1:fx, gx), pos_zero)
            end
            checker("SELBTZ-TwoSum-M1Gx-Y",
                (same_sign == lby) &
                (fy > ex + 1) & (gy < gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy-1:fy, gy), pos_zero)
            end

            checker("SELBTZ-TwoSum-M1Gy-X",
                (same_sign == lbx) &
                (fx > ey) & (gx < ey + 1) & (gx > gy) &
                (ex < gy + p) &
                ((fx > ey + 1) | (!lby & (gx < ey) & (gx > fy)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, fx-1:fx, gy), pos_zero)
            end
            checker("SELBTZ-TwoSum-M1Gy-Y",
                (same_sign == lby) &
                (fy > ex) & (gy < ex + 1) & (gy > gx) &
                (ey < gx + p) &
                ((fy > ex + 1) | (!lbx & (gy < ex) & (gy > fx)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, fy-1:fy, gx), pos_zero)
            end

            checker("SELBTZ-TwoSum-O8-X",
                diff_sign & !lbx &
                (fx > ey + 1) & (gx < fy) &
                (ex > gy + p)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex, fx-1:fx, ex-(p-1):ey), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, fx, ey+1:fx), SELBTZRange(±, 0, gy, gy-p, gy))
                for ee = gy+1:ex-(p+1)
                    add_case!(lemma, SELBTZRange(sx, 0, ex, fx-1:fx, ex-(p-1):ey), SELBTZRange(±, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, 0, ex, fx-1:fx, ex-(p-1):ey), SELBTZRange(±, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, 0, ex, fx-1:fx, ex-(p-1):ey), SELBTZRange(±, 1, ee, gy+1:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, 0, ex, fx, ey+1:fx), SELBTZRange(±, 1, ee, gy-1, gy))
                    add_case!(lemma, SELBTZRange(sx, 0, ex, fx, ey+1:fx), SELBTZRange(±, 0, ee, gy:ee-2, gy))
                    add_case!(lemma, SELBTZRange(sx, 0, ex, fx, ey+1:fx), SELBTZRange(±, 1, ee, gy+1:ee-2, gy))
                end
            end
