                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, fx+1), SELBTZRange(~sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex, gx+2:fx), SELBTZRange(sx, 0, gx, gx-p, gx))
