                add_case!(lemma, SELBTZRange(sy, 1, gx+p, ey-(p-5), fx), SELBTZRange(±, 0, gx, gx-p, gx))
            end

            checker("SELBTZ-TwoSum-W6a-Hxx2+N1+F1+Vxx2+Vyypm4~Hxx2+N1+F1+Vxxpm3+Vyy1-X",
                same_sign & !lbx & !lby &
                (ex == fy + 3) & (fx == ey - 1) &
                (
                    ((ex == gx + (p-1)) & (gy == fy - 1)) |
                    ((ex == gy + (p-1)) & (gx == fy - 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ex-(p-1), ex+1), SELBTZRange(sy, 0, ex-(p-1), ex-(p+p-1), ex-(p-1)))
                for gs = ex-(p-3):ex-5
                    add_case!(lemma, SELBTZRange(sx, 0, ex+1, gs:ex-3, gs), SELBTZRange(±, 0, ex-(p-1), ex-(p+p-1), ex-(p-1)))
                end
                for fs = ex-4:ex-3
                    add_case!(lemma, SELBTZRange(sx, 0, ex+1, fs, fs), SELBTZRange(±, 0, ex-(p-1), ex-(p+p-1), ex-(p-1)))
                end
                add_case!(lemma, SELBTZRange(sx, 0, ex+1, ex-3, ex-4), SELBTZRange(~sy, 0, ex-(p-1), ex-(p+p-1), ex-(p-1)))
                add_case!(lemma, SELBTZRange(sx, 1, ex, ex-p, ex-(p-1)), pos_zero)
                add_case!(lemma, SELBTZRange(sx, 1, ex, ex-(p-2):ex-5, ex-(p-1)), pos_zero)
            end
            checker("SELBTZ-TwoSum-W6a-Hxx2+N1+F1+Vxx2+Vyypm4~Hxx2+N1+F1+Vxxpm3+Vyy1-Y",
                same_sign & !lby & !lbx &
                (ey == fx + 3) & (fy == ex - 1) &
                (
                    ((ey == gy + (p-1)) & (gx == fx - 1)) |
                    ((ey == gx + (p-1)) & (gy == fx - 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ey-(p-1), ey+1), SELBTZRange(sx, 0, ey-(p-1), ey-(p+p-1), ey-(p-1)))
                for gs = ey-(p-3):ey-5
                    add_case!(lemma, SELBTZRange(sy, 0, ey+1, gs:ey-3, gs), SELBTZRange(±, 0, ey-(p-1), ey-(p+p-1), ey-(p-1)))
                end
                for fs = ey-4:ey-3
                    add_case!(lemma, SELBTZRange(sy, 0, ey+1, fs, fs), SELBTZRange(±, 0, ey-(p-1), ey-(p+p-1), ey-(p-1)))
                end
                add_case!(lemma, SELBTZRange(sy, 0, ey+1, ey-3, ey-4), SELBTZRange(~sx, 0, ey-(p-1), ey-(p+p-1), ey-(p-1)))
                add_case!(lemma, SELBTZRange(sy, 1, ey, ey-p, ey-(p-1)), pos_zero)
                add_case!(lemma, SELBTZRange(sy, 1, ey, ey-(p-2):ey-5, ey-(p-1)), pos_zero)
            end

            checker("SELBTZ-TwoSum-W6a-Hxx3+N1+F0+K1+Jxyp-X",
                same_sign & !lbx & !lby &
                (ex == fx + 3) & (ex == gx + (p-1)) & (fx == fy) & (ey == fy + 2) & (ey == gy + (p-1))
            ) do lemma
                for gs = gy+2:fx
                    add_case!(lemma, SELBTZRange(sx, 1, ex, gs-1, gs), SELBTZRange(±, 0, gy, gy-p, gy))
                    add_case!(lemma, SELBTZRange(sx, 1, ex, gs+1:fx, gs), SELBTZRange(±, 0, gy, gy-p, gy))
                end
            end
            checker("SELBTZ-TwoSum-W6a-Hxx3+N1+F0+K1+Jxyp-Y",
                same_sign & !lby & !lbx &
                (ey == fy + 3) & (ey == gy + (p-1)) & (fy == fx) & (ex == fx + 2) & (ex == gx + (p-1))
            ) do lemma
                for gs = gx+2:fy
                    add_case!(lemma, SELBTZRange(sy, 1, ey, gs-1, gs), SELBTZRange(±, 0, gx, gx-p, gx))
                    add_case!(lemma, SELBTZRange(sy, 1, ey, gs+1:fy, gs), SELBTZRange(±, 0, gx, gx-p, gx))
                end
            end

            checker("SELBTZ-TwoSum-W6e-Hxx3+N2+Jyx3+F1+Jxyp1-X",
                diff_sign & !lbx & lby &
                (ex == ey + 2) & (ex == gy + (p+1)) & (fx == ey - 1) & (gx == fx - 2) & (fy == ey - 2)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ey+1, fx, ey-(p-3):fy-2), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey-1, ex-(p-1):fy), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, ey-1, ey), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ey+1, fx, fx-2), SELBTZRange(~sy, 0, gy, gy-p, gy))
            end
            checker("SELBTZ-TwoSum-W6e-Hxx3+N2+Jyx3+F1+Jxyp1-Y",
                diff_sign & !lby & lbx &
                (ey == ex + 2) & (ey == gx + (p+1)) & (fy == ex - 1) & (gy == fy - 2) & (fx == ex - 2)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ex+1, fy, ex-(p-3):fx-2), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex-1, ey-(p-1):fx), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, ex-1, ex), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ex+1, fy, fy-2), SELBTZRange(~sx, 0, gx, gx-p, gx))
            end

            checker("SELBTZ-TwoSum-B2a-Hxx3+N2+Jyx3+F1+Qy0:1-X",
                (same_sign != lbx) & !lby &
                (ex == ey + 2) & (fx == ey - 1) & (fx == fy + 1) & (gx == fy - 1) &
                ((ex == gy + p) | (ex == gy + (p+1)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, gy+2:fy-2), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, lbx, ex, ey, fy-1), SELBTZRange(sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, ~lbx, ex, ex-2, gy+2:fy), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, ex-2, ex-1), SELBTZRange(±, 0, gy, gy-p, gy))
            end
            checker("SELBTZ-TwoSum-B2a-Hxx3+N2+Jyx3+F1+Qy0:1-Y",
                (same_sign != lby) & !lbx &
                (ey == ex + 2) & (fy == ex - 1) & (fy == fx + 1) & (gy == fx - 1) &
                ((ey == gx + p) | (ey == gx + (p+1)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, gx+2:fx-2), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, lby, ey, ex, fx-1), SELBTZRange(sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, ~lby, ey, ey-2, gx+2:fx), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, ey-2, ey-1), SELBTZRange(±, 0, gx, gx-p, gx))
            end

            checker("SELBTZ-TwoSum-B2a-Hxx3+N1+F1+Vyx0+Qy0~Hxx4+N1+Fm1+Vyx0+Qy0-X",
                diff_sign & lbx & !lby &
                (ex == ey + 1) & (ex == gy + p) & (gx == fy) &
                (
                    ((ex == fy + 3) & (fy == fx + 1)) |
                    ((ex == fy + 4) & (fx == fy + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex, ex-2, ex-2), SELBTZRange(sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, ex-3, gy+2:fy-1), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 0, ex, ex-3, fy), SELBTZRange(~sy, 0, gy, gy-p, gy))
            end
            checker("SELBTZ-TwoSum-B2a-Hxx3+N1+F1+Vyx0+Qy0~Hxx4+N1+Fm1+Vyx0+Qy0-Y",
                diff_sign & lby & !lbx &
                (ey == ex + 1) & (ey == gx + p) & (gy == fx) &
                (
                    ((ey == fx + 3) & (fx == fy + 1)) |
                    ((ey == fx + 4) & (fy == fx + 1))
                )
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey, ey-2, ey-2), SELBTZRange(sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey, ey-3, gx+2:fx-1), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 0, ey, ey-3, fx), SELBTZRange(~sx, 0, gx, gx-p, gx))
            end

            checker("SELBTZ-TwoSum-B2a-Hxx3+N2+F1+Vyx0+Qy0:1-X",
                (same_sign != lbx) & !lby &
                (ex == ey + 2) & (gx == fx - 1) & (gx == ey - 2) & (gx == fy) &
                ((ex == gy + p) | (ex == gy + (p+1)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, ey, ey+1), SELBTZRange(sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, ~lbx, ex, ey, gy+2:fy-1), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, ~lbx, ex, ey, fy), SELBTZRange(~sy, 0, gy, gy-p, gy))
            end
            checker("SELBTZ-TwoSum-B2a-Hxx3+N2+F1+Vyx0+Qy0:1-Y",
                (same_sign != lby) & !lbx &
                (ey == ex + 2) & (gy == fy - 1) & (gy == ex - 2) & (gy == fx) &
                ((ey == gx + p) | (ey == gx + (p+1)))
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, ex, ex+1), SELBTZRange(sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, ~lby, ey, ex, gx+2:fx-1), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, ~lby, ey, ex, fx), SELBTZRange(~sx, 0, gx, gx-p, gx))
            end

            checker("SELBTZ-TwoSum-B2a-Hxx4+N1+Jyx3+Fm1+Qy0-X",
                same_sign & !lbx & !lby &
                (ex == ey + 1) & (ex == gy + p) & (fx == gx) & (fx == ey - 3) & (fx == fy - 1)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, fy+1), SELBTZRange(±, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy, fx), SELBTZRange(~sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy+1, fx), SELBTZRange(sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex, fy:fy+1, gy+2:fx-1), SELBTZRange(±, 0, gy, gy-p, gy))
            end
            checker("SELBTZ-TwoSum-B2a-Hxx4+N1+Jyx3+Fm1+Qy0-Y",
                same_sign & !lby & !lbx &
                (ey == ex + 1) & (ey == gx + p) & (fy == gy) & (fy == ex - 3) & (fy == fx - 1)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, fx+1), SELBTZRange(±, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx, fy), SELBTZRange(~sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx+1, fy), SELBTZRange(sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey, fx:fx+1, gx+2:fy-1), SELBTZRange(±, 0, gx, gx-p, gx))
            end

            checker("SELBTZ-TwoSum-R4f-Hxxpm3+Hyx0+F2+Vyx0+K1-X",
                diff_sign & !lbx & !lby &
                (ex == gy + p) & (fx == ey) & (fx == fy + 2) & (gx == fy) & (gx == gy + 1)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex, gx+1, gx+1), SELBTZRange(sy, 0, gy, gy-p, gy))
                add_case!(lemma, SELBTZRange(sx, 1, ex-1, gy-1, gy), pos_zero)
            end
            checker("SELBTZ-TwoSum-R4f-Hxxpm3+Hyx0+F2+Vyx0+K1-Y",
                diff_sign & !lby & !lbx &
                (ey == gx + p) & (fy == ex) & (fy == fx + 2) & (gy == fx) & (gy == gx + 1)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey, gy+1, gy+1), SELBTZRange(sx, 0, gx, gx-p, gx))
                add_case!(lemma, SELBTZRange(sy, 1, ey-1, gx-1, gx), pos_zero)
            end

            checker("SELBTZ-TwoSum-U-Hxxp+Jxx0+N2+Qy0+Vyym1-D01-X",
                diff_sign & !lbx & lby &
                (ex == ey + 2) & (ex == fy + (p+2)) & (gx == ex)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 0, ex-1, gy, ex-1), SELBTZRange(~sy, 0, gy, gy-p, gy))
            end
            checker("SELBTZ-TwoSum-U-Hxxp+Jxx0+N2+Qy0+Vyym1-D01-Y",
                diff_sign & !lby & lbx &
                (ey == ex + 2) & (ey == fx + (p+2)) & (gy == ey)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 0, ey-1, gx, ey-1), SELBTZRange(~sx, 0, gx, gx-p, gx))
            end

            checker("SELBTZ-TwoSum-U-Nm1+Vxx0+Hyyp+Jyy0+Qx0-S00-X",
                same_sign & !lbx & !lby &
                (ex == gx + (p-1)) & (fx == gx) & (ey == ex + 1) & (ey == gy)
            ) do lemma
                add_case!(lemma, SELBTZRange(sx, 1, ex+1, ex-1, ex), SELBTZRange(sy, 0, gx, gx-p, gx))
            end
            checker("SELBTZ-TwoSum-U-Nm1+Vxx0+Hyyp+Jyy0+Qx0-S00-Y",
                same_sign & !lby & !lbx &
                (ey == gy + (p-1)) & (fy == gy) & (ex == ey + 1) & (ex == gx)
            ) do lemma
                add_case!(lemma, SELBTZRange(sy, 1, ey+1, ey-1, ey), SELBTZRange(sx, 0, gy, gy-p, gy))
            end

        end
        #! format: on

        if !isone(length(checker.covering_lemmas))
            error("Abstract SELBTZ-TwoSum-$T inputs ($x, $y) are not covered " *
                "by exactly one lemma.")
        end
    end

    println("SELBTZ-TwoSum-$T lemmas:")
    for (name, n) in sort!(collect(lemma_counts))
        println("    $name: $n")
    end
    flush(stdout)

    return nothing
end


function main_two_sum(::Type{SoftFloat{P}}) where {P}
    value_map = compute_value_map(SELBTZAbstraction, SoftFloat{P}, -2, P)
    check_selbtz_two_sum_lemmas(value_map)
    println("Successfully checked all SELBTZ-TwoSum lemmas at precision $P.")
    flush(stdout)
    return nothing
end


if abspath(PROGRAM_FILE) == @__FILE__
    for P = 7:12
        main_two_sum(SoftFloat{P})
    end
end
